-- @ Q3.1 os.count_parts: prosrc alone (what it lacks: the header) vs pg_get_functiondef (search_path '')
set search_path = ''; select pg_catalog.quote_literal(p.prosrc) as prosrc, pg_catalog.pg_get_functiondef(p.oid) as functiondef from pg_catalog.pg_proc p where p.oid = 'os.count_parts'::regproc;
-- @ Q3.2 where each property is read: prosecdef, proconfig (raw order: the file said work_mem first), provolatile, proisstrict, proparallel, proleakproof, procost, prorows, prokind, proretset, owner, proacl, pronargdefaults, pg_get_function_arguments / identity / result, prosupport, prolang
select p.oid::regprocedure::text, p.prosecdef, p.proconfig::text, p.provolatile, p.proisstrict, p.proparallel, p.proleakproof, p.procost, p.prorows, p.prokind, p.proretset, pg_catalog.pg_get_userbyid(p.proowner), p.proacl::text, p.pronargdefaults, pg_catalog.pg_get_function_arguments(p.oid), pg_catalog.pg_get_function_identity_arguments(p.oid), pg_catalog.pg_get_function_result(p.oid), p.prosupport::text, (select lanname from pg_catalog.pg_language where oid = p.prolang) from pg_catalog.pg_proc p where p.pronamespace = 'os'::regnamespace order by 1;
-- @ Q3.3 proacl null: what the server takes it to mean — acldefault('f', owner) exploded (a function made by a role whose default ACL does not revoke PUBLIC): made in a rolled-back transaction as the installer in schema public
begin; create function public.h6_null_acl() returns int language sql as $f$ select 1 $f$; select p.proacl is null as acl_is_null, (select pg_catalog.string_agg(case a.grantee when 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(a.grantee) end || ':' || a.privilege_type || ':' || a.is_grantable::text || ':by ' || pg_catalog.pg_get_userbyid(a.grantor), ', ') from pg_catalog.aclexplode(pg_catalog.acldefault('f', p.proowner)) a) as effective_from_acldefault, pg_catalog.has_function_privilege('anon', p.oid, 'execute') as anon_may_execute from pg_catalog.pg_proc p where p.oid = 'public.h6_null_acl'::regproc; rollback;
-- @ Q3.3b the same function, but made by the installer in public: did the platform's default privileges fill proacl at creation?
begin; create function public.h6_null_acl() returns int language sql as $f$ select 1 $f$; select p.proacl::text from pg_catalog.pg_proc p where p.oid = 'public.h6_null_acl'::regproc; rollback;
-- @ Q3.4 os functions: proacl is stored (not null) because os_owner's global default revokes PUBLIC EXECUTE — acldefault for os_owner vs the stored ACL
select p.oid::regprocedure::text, p.proacl::text as stored, pg_catalog.acldefault('f', p.proowner)::text as acldefault_for_owner from pg_catalog.pg_proc p where p.pronamespace = 'os'::regnamespace order by 1;
-- @ Q3.5 leakproof: may the owner (os_owner, via set role) make one? (rolled back)
begin; set local role os_owner; create function os.h6_lp(int) returns int language sql leakproof as $f$ select 1 $f$; rollback;
-- @ Q3.6 leakproof as the installer itself (rolled back)
begin; create function public.h6_lp(int) returns int language sql leakproof as $f$ select 1 $f$; rollback;
